use semio_s_artifact_stdio_idml::io::admission::change::retained_part::RetainedIdmlPartPatch;
use semio_framework_value::{RetirementDemand,retained_clone::RetainedCloneGrant};
use semio_framework_value::{retirement::RetireOwned,retained_clone::RetainedCloneSource};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn underfunded(d:RetirementDemand)->Vec<RetainedCloneGrant>{let g=grant(d);let mut rows=vec![RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}];if d.copy_bytes!=0{rows.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g});}if d.capacity_bytes!=0{rows.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g});}if d.release_bytes!=0{rows.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g});}rows}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096};match RetainedCloneSource::admit_owned(value,(),g){Ok((source,_))=>source,Err((error,_,_))=>panic!("{error}")}}
fn close_source<T:RetireOwned+Sync+'static>(source:&mut RetainedCloneSource<T>){for _ in 0..100000{if source.terminal_is_empty(){return;}let d=RetirementDemand{copy_bytes:source.next_close_copy_byte_demand().unwrap(),capacity_bytes:source.next_close_capacity_byte_demand(4096).unwrap(),release_bytes:source.next_close_release_byte_demand().unwrap(),depth:source.next_close_depth_demand().unwrap()};source.close_step(grant(d)).unwrap();}panic!("original field source close stalled");}
fn close(owner:&mut RetainedIdmlPartPatch){owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){return;}let d=owner.close_demand(4096).unwrap();for g in underfunded(d){assert_eq!(owner.close_step(g).unwrap().progress(),Default::default());}owner.close_step(grant(d)).unwrap();}panic!("partial member close stalled");}
#[test]
fn genuine_fields_form_one_serializable_sparse_member(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){let name=row["path"].as_str().unwrap().to_string();let payload=if let Some(text)=row["text"].as_str(){Some(text.as_bytes().to_vec())}else if row["bytes"].is_null(){None}else{Some(row["bytes"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap() as u8).collect::<Vec<_>>())};let mut original_path=source(name.clone());let mut original_bytes=payload.clone().map(source);
 for body in [1024,4096,65536]{let mut owner=RetainedIdmlPartPatch::new(payload.is_none());for _ in 0..100000{if owner.ready(){break;}let bytes=original_bytes.as_ref().map(|s|s.borrow());let d=owner.demand(original_path.borrow(),bytes,body).unwrap();for g in underfunded(d){assert_eq!(owner.advance(original_path.borrow(),original_bytes.as_ref().map(|s|s.borrow()),body,g).unwrap().progress(),Default::default());}owner.advance(original_path.borrow(),original_bytes.as_ref().map(|s|s.borrow()),body,grant(d)).unwrap();}assert!(owner.ready());let d=owner.take_demand().unwrap();for g in underfunded(d){assert!(owner.take(g).unwrap().0.is_none());}let(value,_)=owner.take(grant(d)).unwrap();let value=value.unwrap();assert_eq!(value.path,name);assert_eq!(value.bytes,payload);let mut output=source(value);close_source(&mut output);close(&mut owner);}
 for cut in [0,1,2,10,30]{let mut owner=RetainedIdmlPartPatch::new(payload.is_none());for _ in 0..cut{if owner.ready(){break;}let d=owner.demand(original_path.borrow(),original_bytes.as_ref().map(|s|s.borrow()),1024).unwrap();owner.advance(original_path.borrow(),original_bytes.as_ref().map(|s|s.borrow()),1024,grant(d)).unwrap();}close(&mut owner);assert_eq!(original_path.borrow().get(),&name);if let Some(bytes)=&original_bytes{assert_eq!(Some(bytes.borrow().get()),payload.as_ref());}}
 if let Some(bytes)=&mut original_bytes{close_source(bytes);}close_source(&mut original_path);
 }
}
